export function buildReportPage(input: ReportInput): ReportPage {
  const s = summarize(input.results); // -> { total, passed, failed }
  const cards: StatCard[] = [
    { label: 'Agents', value: s.total },
    { label: 'Passed', value: s.passed, tone: 'pass' },
    // Only tint the Failed tile red when something actually failed.
    { label: 'Failed', value: s.failed, tone: s.failed ? 'fail' : 'neutral' },
  ];
  const sections = [
    section('Summary', statCards(cards)),
    section('Results', table(
      ['Agent', 'Status', 'Summary', 'Steps'],
      // Badge tone follows r.ok; ?. || 0 guards a result with no steps array.
      input.results.map(r => [r.agent, badge(r.ok ? 'PASS' : 'FAIL', r.ok ? 'pass' : 'fail'), r.summary, String(r.steps?.length || 0)]),
    )),
  ];
  for (const r of input.results) {
    // One evidence section per result that HAS steps — skip empty ones.
    if (r.steps?.length) sections.push(section(`Evidence — ${r.agent}`, evidenceSteps(r.steps)));
  }
  return { title: input.title, subtitle: input.subtitle, generatedAt: input.generatedAt, sections };
}

export function statCards(items: StatCard[]): string {
  // Clamp columns to 1..4 so the grid never looks starved or overcrowded.
  const cols = Math.min(Math.max(items.length, 1), 4);
  const cards = items.map(it => {
    // Tint the number from a CSS token (--pass/--fail/...), only for a real tone.
    const numStyle = it.tone && it.tone !== 'neutral' ? ` style="color:var(--${it.tone})"` : '';
    // escapeHtml on BOTH value and label — untrusted content can't inject markup.
    return `<div class="card stat">
  <div class="num"${numStyle}>${escapeHtml(String(it.value))}</div>
  <div class="lbl">${escapeHtml(it.label)}</div>
</div>`;
  }).join('\n');
  return `<div class="grid cols-${cols}">\n${cards}\n</div>`;
}

:root {
  --accent: #4f46e5;         /* indigo — primary */
  --pass: #16a34a;           /* green — passing checks */
  --fail: #dc2626;           /* red — failing checks */
  --warn: #d97706;
  --info: #2563eb;
}
/* Dark theme re-points the SAME token names — every helper picks it up for free. */
@media (prefers-color-scheme: dark) {
  :root {
    --accent: #818cf8;
    --pass: #4ade80; --fail: #f87171; --warn: #fbbf24; --info: #60a5fa;
  }
}

export function htmlDocument(opts: { title: string; bodyHtml: string; extraCss?: string }): string {
  // Inline THEME_CSS (+ any extraCss) into <head> so the file needs no network.
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${escapeHtml(opts.title)}</title>
<style>${THEME_CSS}${opts.extraCss || ''}</style>
</head>
<body>
${opts.bodyHtml}
</body>
</html>`;
}

export function runReportAgent(input: ReportInput, outPath: string): AgentResult<{ outPath: string }> {
  const rp = buildReportPage(input);
  const abs = saveReport(rp, outPath); // write the page, get its absolute path back.
  const s = summarize(input.results);
  return {
    agent: 'report',
    ok: s.failed === 0, // the report itself "passes" only if no input result failed.
    summary: `Rendered ${input.results.length} agent result(s) — ${s.passed} passed, ${s.failed} failed`,
    data: { outPath: abs },
    // Return a normal AgentResult so a report can feed into a larger report.
    artifacts: [{ path: abs, kind: 'html' }],
  };
}
